from values_fields import number, string, to_number, to_string


class RuntimeIssue(Exception):
    def __init__(self, position, message):
        super().__init__(message)
        self.position, self.message = position, message


def format_output(arguments, position):
    fmt = to_string(arguments[0])
    pieces = []
    index, argument_index = 0, 1
    while index < len(fmt):
        if fmt[index] != "%":
            pieces.append(fmt[index])
            index += 1
            continue
        index += 1
        if index < len(fmt) and fmt[index] == "%":
            pieces.append("%")
            index += 1
            continue
        flags = set()
        while index < len(fmt) and fmt[index] in "-0":
            flags.add(fmt[index])
            index += 1
        start = index
        while index < len(fmt) and "0" <= fmt[index] <= "9":
            index += 1
        width = int(fmt[start:index]) if start < index else 0
        precision = None
        if index < len(fmt) and fmt[index] == ".":
            index += 1
            start = index
            while index < len(fmt) and "0" <= fmt[index] <= "9":
                index += 1
            precision = int(fmt[start:index]) if start < index else 0
        if index == len(fmt) or fmt[index] not in "discxo":
            raise RuntimeIssue(position, "invalid format")
        conversion = fmt[index]
        index += 1
        if argument_index == len(arguments):
            raise RuntimeIssue(position, "not enough arguments")
        value = arguments[argument_index]
        argument_index += 1
        numeric = conversion in "dixo"
        if numeric:
            integer = to_number(value)
            base = "d" if conversion in "di" else conversion
            digits = format(abs(integer), base)
            if precision is not None:
                digits = "" if precision == 0 and integer == 0 else digits.rjust(precision, "0")
            body = ("-" if integer < 0 else "") + digits
        elif conversion == "s":
            body = to_string(value)
            if precision is not None:
                body = body[:precision]
        else:
            if value.kind in ("number", "strnum"):
                code = to_number(value)
                if code != 10 and not 32 <= code <= 126:
                    raise RuntimeIssue(position, "invalid character code")
                body = chr(code)
            else:
                body = to_string(value)[:1]
        missing = width - len(body)
        if missing > 0:
            if "-" in flags:
                body += " " * missing
            elif numeric and "0" in flags and precision is None:
                if body.startswith("-"):
                    body = "-" + "0" * missing + body[1:]
                else:
                    body = "0" * missing + body
            else:
                body = " " * missing + body
        pieces.append(body)
    return "".join(pieces)


def invoke(name, arguments, position):
    if name == "sprintf":
        return string(format_output(arguments, position))
    if name == "int":
        return number(to_number(arguments[0]))
    text = to_string(arguments[0])
    if name == "substr":
        start = to_number(arguments[1])
        end = start + to_number(arguments[2]) if len(arguments) == 3 else len(text) + 1
        start, end = max(start, 1), min(end, len(text) + 1)
        return string(text[start - 1:end - 1] if end > start else "")
    if name == "index":
        sought = to_string(arguments[1])
        return number(text.find(sought) + 1 if sought else 0)
    if name == "toupper":
        return string("".join(chr(ord(character) - 32) if "a" <= character <= "z" else character for character in text))
    if name == "tolower":
        return string("".join(chr(ord(character) + 32) if "A" <= character <= "Z" else character for character in text))
    raise ValueError(name)

from collections import namedtuple


Token = namedtuple("Token", "kind spelling value position")
KEYWORDS = frozenset("BEGIN END function if else while for do break continue next exit return delete in getline print printf".split())
BUILTINS = frozenset("length substr index split sprintf toupper tolower close int".split())
PAIRS = frozenset(("+=", "-=", "*=", "/=", "%=", "^=", "==", "<=", ">=", "!=", "++", "--", "&&", "||", ">>"))
SYMBOLS = frozenset("+-*/%^!><?:=()[]{},;$")
ESCAPES = {"n": "\n", "t": "\t", "\\": "\\", '"': '"', "/": "/"}


class SyntaxIssue(Exception):
    def __init__(self, position):
        super().__init__(position)
        self.position = position


def letter(character):
    return "a" <= character <= "z" or "A" <= character <= "Z" or character == "_"


def digit(character):
    return "0" <= character <= "9"


def tokenize(source):
    tokens = []
    index, line, column = 0, 1, 1
    while index < len(source):
        character = source[index]
        start = line, column
        if character == " ":
            index += 1
            column += 1
            continue
        if source.startswith("\\\n", index):
            index += 2
            line += 1
            column = 1
            continue
        if character == "#":
            end = source.find("\n", index)
            if end < 0:
                end = len(source)
            column += end - index
            index = end
            continue
        if character == "\n":
            tokens.append(Token("newline", "\n", None, start))
            index += 1
            line += 1
            column = 1
            continue
        end = index + 1
        value = None
        if digit(character):
            while end < len(source) and digit(source[end]):
                end += 1
            kind, value = "number", int(source[index:end])
        elif letter(character):
            while end < len(source) and (letter(source[end]) or digit(source[end])):
                end += 1
            word = source[index:end]
            if word in KEYWORDS:
                kind = "keyword"
            elif word in BUILTINS:
                kind = "builtin"
            else:
                kind = "function_name" if end < len(source) and source[end] == "(" else "name"
        elif character == '"':
            pieces = []
            while end < len(source) and source[end] != '"':
                if source[end] == "\n":
                    raise SyntaxIssue(start)
                if source[end] == "\\":
                    if end + 1 == len(source) or source[end + 1] not in ESCAPES:
                        raise SyntaxIssue((line, column + end - index))
                    pieces.append(ESCAPES[source[end + 1]])
                    end += 2
                else:
                    pieces.append(source[end])
                    end += 1
            if end == len(source):
                raise SyntaxIssue(start)
            end += 1
            kind, value = "string", "".join(pieces)
        elif source[index:index + 2] in PAIRS:
            end += 1
            kind = "symbol"
        elif character in SYMBOLS:
            kind = "symbol"
        else:
            raise SyntaxIssue(start)
        tokens.append(Token(kind, source[index:end], value, start))
        column += end - index
        index = end
    tokens.append(Token("end", "", None, (source.count("\n") + 1, 1)))
    return tokens

from pathlib import Path
import sys

import awk_builtins
from awk_builtins import RuntimeIssue
from lexer import SyntaxIssue, tokenize
from parser import COMPARISONS, STATEMENTS, Parser
from streams import Streams, parse_arguments, read_records
from values_fields import (UNINITIALIZED, Record, compare, describe, input_value, number,
                           split_pieces, string, subscript_order, to_number, to_string, truth)


SPECIAL_NAMES = frozenset(("FILENAME", "FNR", "FS", "NF", "NR", "OFS", "ORS", "SUBSEP"))


class StaticIssue(Exception):
    def __init__(self, position, message):
        super().__init__(message)
        self.position, self.message = position, message


class Transfer(Exception):
    def __init__(self, kind, value=UNINITIALIZED):
        super().__init__(kind)
        self.kind, self.value = kind, value


class Analysis:
    def __init__(self, items):
        self.items = items
        self.functions = [item for item in items if item.kind == "function"]
        self.rules = [item for item in items if item.kind == "rule"]
        self.function_table = {}
        self.global_names = set(SPECIAL_NAMES)
        self.bindings = {(None, name) for name in SPECIAL_NAMES}
        self.array_names = set()
        self.statement_lines = set()
        self.nodes = []
        self.errors = []

    def error(self, position, priority, message):
        self.errors.append((position, priority, message))

    def declarations(self):
        for function in self.functions:
            if function.name in self.function_table:
                self.error(function.name_position, 0, f"function {function.name} redefined")
            else:
                self.function_table[function.name] = function
            function.parameter_names = set()
            for parameter in function.parameters:
                if parameter.name in function.parameter_names:
                    self.error(parameter.position, 1, f"duplicate parameter {parameter.name}")
                function.parameter_names.add(parameter.name)

    def resolve(self, node, function):
        local = function is not None and node.name in function.parameter_names
        binding = (function if local else None, node.name)
        node.binding = binding
        self.bindings.add(binding)
        if not local:
            self.global_names.add(node.name)
        if node.name in self.function_table:
            self.error(node.position, 2, f"function {node.name} used as variable")

    def collect(self):
        for item in self.items:
            function = item if item.kind == "function" else None
            pending = [item]
            while pending:
                node = pending.pop()
                self.nodes.append(node)
                if node.kind in STATEMENTS:
                    self.statement_lines.add(node.position[0])
                if node.kind in ("name", "array", "parameter"):
                    self.resolve(node, function)
                elif node.kind == "call":
                    target = self.function_table.get(node.name)
                    if target is None:
                        self.error(node.position, 3, f"undefined function {node.name}")
                    else:
                        node.function = target
                        if len(node.arguments) > len(target.parameters):
                            self.error(node.position, 4, f"too many arguments to {node.name}")
                pending.extend(reversed(node.children))

    def arrays(self):
        links = []
        for node in self.nodes:
            if node.kind == "array":
                self.array_names.add(node.binding)
            elif node.kind in ("membership", "delete", "for_in"):
                self.array_names.add(node.array.binding)
            elif node.kind == "builtin" and node.name == "split":
                self.array_names.add(node.arguments[1].binding)
            elif node.kind == "call":
                for argument, parameter in zip(node.arguments, node.function.parameters):
                    if argument.kind == "name":
                        links.append((argument.binding, parameter.binding))
        parents = {binding: binding for binding in self.bindings}

        def root(binding):
            while parents[binding] != binding:
                parents[binding] = parents[parents[binding]]
                binding = parents[binding]
            return binding

        for first, second in links:
            parents[root(first)] = root(second)
        array_roots = {root(binding) for binding in self.array_names}
        self.array_names = {binding for binding in self.bindings if root(binding) in array_roots}

    def prepare(self):
        self.declarations()
        self.collect()
        if self.errors:
            position, priority, message = min(self.errors)
            raise StaticIssue(position, message)
        self.arrays()
        return self


def arithmetic(operator, first, second, position):
    a, b = to_number(first), to_number(second)
    if operator in ("/", "%"):
        if b == 0:
            raise RuntimeIssue(position, "division by zero")
        quotient = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            quotient = -quotient
        result = quotient if operator == "/" else a - quotient * b
    elif operator == "^":
        if b < 0:
            raise RuntimeIssue(position, "negative exponent")
        result = a ** b
    elif operator == "+":
        result = a + b
    elif operator == "-":
        result = a - b
    else:
        result = a * b
    return number(result)


class Engine:
    def __init__(self, analysis, options, operands):
        self.analysis, self.options, self.operands = analysis, options, operands
        self.global_names = set(analysis.global_names)
        self.globals = {name: {} if (None, name) in analysis.array_names else UNINITIALIZED
                        for name in self.global_names}
        self.globals.update(FILENAME=string(""), FNR=number(0), FS=string(" "), NF=number(0),
                            NR=number(0), OFS=string(" "), ORS=string("\n"), SUBSEP=string(chr(28)))
        self.locals = []
        self.record = Record(lambda name: self.globals[name])
        self.streams = Streams()
        self.lines = {line: 0 for line in analysis.statement_lines}
        self.phase = "BEGIN"
        self.exit_status = 0
        self.error = None
        self.operand_position = 0
        self.current_operand = None
        self.input_lines = []
        self.input_position = 0
        for rule in analysis.rules:
            rule.count = 0
            rule.inside = False
        for function in analysis.functions:
            function.call_count = 0
            function.active_calls = 0
            function.max_depth = 0

    def variable(self, binding):
        scope, name = binding
        if scope is not None:
            return self.locals[-1][name]
        if name == "NF":
            return number(len(self.record.fields))
        return self.globals[name]

    def global_value(self, name):
        return self.variable((None, name))

    def assign_global_input(self, name, text):
        self.global_names.add(name)
        self.globals[name] = input_value(text)

    def subscript(self, expressions):
        values = []
        for expression in expressions:
            values.append(to_string(self.evaluate(expression)))
        separator = to_string(self.global_value("SUBSEP"))
        return separator.join(values)

    def location(self, node):
        if node.kind == "name":
            return "variable", node.binding
        if node.kind == "array":
            key = self.subscript(node.indexes)
            return "array", self.variable(node.binding), key
        index = to_number(self.evaluate(node.index))
        if index < 0:
            raise RuntimeIssue(node.position, "negative field index")
        return "field", index

    def read(self, location):
        kind = location[0]
        if kind == "variable":
            return self.variable(location[1])
        if kind == "field":
            return self.record.read(location[1])
        array, key = location[1:]
        if key not in array:
            array[key] = UNINITIALIZED
        return array[key]

    def store(self, location, value, position):
        kind = location[0]
        if kind == "field":
            self.record.write(location[1], value)
        elif kind == "array":
            location[1][location[2]] = value
        else:
            scope, name = location[1]
            if scope is not None:
                self.locals[-1][name] = value
            elif name == "NF":
                size = to_number(value)
                if size < 0:
                    raise RuntimeIssue(position, "negative NF")
                self.record.resize(size)
            else:
                self.globals[name] = value

    def evaluate(self, node):
        kind = node.kind
        if kind == "number":
            return number(node.value)
        if kind == "string":
            return string(node.value)
        if kind in ("name", "array", "field"):
            return self.read(self.location(node))
        if kind == "paren":
            return self.evaluate(node.expression)
        if kind == "assignment":
            location = self.location(node.location)
            value = self.evaluate(node.value)
            if node.operator != "=":
                value = arithmetic(node.operator[:-1], self.read(location), value, node.position)
            self.store(location, value, node.position)
            return self.read(location)
        if kind == "increment":
            location = self.location(node.location)
            old = to_number(self.read(location))
            value = old + node.delta
            self.store(location, number(value), node.position)
            return number(value if node.prefix else old)
        if kind == "conditional":
            branch = node.first if truth(self.evaluate(node.condition)) else node.second
            return self.evaluate(branch)
        if kind == "unary":
            value = self.evaluate(node.operand)
            if node.operator == "!":
                return number(int(not truth(value)))
            integer = to_number(value)
            return number(-integer if node.operator == "-" else integer)
        if kind == "membership":
            key = self.subscript(node.indexes)
            return number(int(key in self.variable(node.array.binding)))
        if kind == "binary":
            first = self.evaluate(node.left)
            operator = node.operator
            if operator == "||" and truth(first):
                return number(1)
            if operator == "&&" and not truth(first):
                return number(0)
            second = self.evaluate(node.right)
            if operator in ("&&", "||"):
                return number(int(truth(second)))
            if operator == "concat":
                return string(to_string(first) + to_string(second))
            if operator in COMPARISONS:
                order = compare(first, second)
                result = {"<": order < 0, "<=": order <= 0, "==": order == 0,
                          "!=": order != 0, ">=": order >= 0, ">": order > 0}[operator]
                return number(int(result))
            return arithmetic(operator, first, second, node.position)
        if kind == "call":
            return self.call(node)
        if kind == "builtin":
            return self.builtin(node)
        return self.getline(node)

    def call(self, node):
        function = node.function
        local = {}
        for index, parameter in enumerate(function.parameters):
            is_array = parameter.binding in self.analysis.array_names
            if index < len(node.arguments):
                argument = node.arguments[index]
                value = self.variable(argument.binding) if is_array else self.evaluate(argument)
            else:
                value = {} if is_array else UNINITIALIZED
            local[parameter.name] = value
        function.call_count += 1
        function.active_calls += 1
        function.max_depth = max(function.max_depth, function.active_calls)
        self.locals.append(local)
        try:
            self.statement(function.body)
        except Transfer as transfer:
            if transfer.kind == "return":
                return transfer.value
            raise
        finally:
            self.locals.pop()
            function.active_calls -= 1
        return UNINITIALIZED

    def builtin(self, node):
        name, arguments = node.name, node.arguments
        if name == "length":
            if not arguments:
                return number(len(to_string(self.record.zero)))
            argument = arguments[0]
            if argument.kind == "name" and argument.binding in self.analysis.array_names:
                return number(len(self.variable(argument.binding)))
            return number(len(to_string(self.evaluate(argument))))
        if name == "split":
            text = to_string(self.evaluate(arguments[0]))
            separator = to_string(self.evaluate(arguments[2])) if len(arguments) == 3 else to_string(self.global_value("FS"))
            array = self.variable(arguments[1].binding)
            array.clear()
            pieces = split_pieces(text, separator)
            for index, piece in enumerate(pieces, 1):
                array[str(index)] = input_value(piece)
            return number(len(pieces))
        if name == "close":
            filename = to_string(self.evaluate(arguments[0]))
            return number(self.streams.close(filename))
        values = [self.evaluate(argument) for argument in arguments]
        return awk_builtins.invoke(name, values, node.position)

    def getline(self, node):
        if node.filename is not None:
            filename = to_string(self.evaluate(node.filename))
            status, line = self.streams.getline(filename)
        elif self.phase == "END":
            return number(0)
        else:
            line = self.next_record()
            status = int(line is not None)
        if status == 1:
            if node.target is None:
                self.record.set(line)
            else:
                location = self.location(node.target)
                self.store(location, input_value(line), node.position)
        return number(status)

    def output(self, node):
        arguments = [self.evaluate(argument) for argument in node.arguments]
        if node.kind == "print":
            if not arguments:
                arguments = [self.record.zero]
            separator = to_string(self.global_value("OFS"))
            text = separator.join(to_string(value) for value in arguments)
            text += to_string(self.global_value("ORS"))
        else:
            text = awk_builtins.format_output(arguments, node.position)
        filename = to_string(self.evaluate(node.filename)) if node.filename is not None else None
        self.streams.write(text, filename, node.redirect, node.redirect_position)

    def loop_body(self, body):
        try:
            self.statement(body)
        except Transfer as transfer:
            if transfer.kind == "break":
                return False
            if transfer.kind != "continue":
                raise
        return True

    def statement(self, node):
        kind = node.kind
        if kind == "block":
            for child in node.statements:
                self.statement(child)
            return
        if kind == "empty":
            return
        self.lines[node.position[0]] += 1
        if kind == "expression_statement":
            self.evaluate(node.expression)
        elif kind in ("print", "printf"):
            self.output(node)
        elif kind == "if":
            branch = node.first if truth(self.evaluate(node.condition)) else node.second
            if branch is not None:
                self.statement(branch)
        elif kind == "while":
            while truth(self.evaluate(node.condition)):
                if not self.loop_body(node.body):
                    break
        elif kind == "do":
            while True:
                if not self.loop_body(node.body):
                    break
                if not truth(self.evaluate(node.condition)):
                    break
        elif kind == "for":
            if node.initial is not None:
                self.evaluate(node.initial)
            while node.condition is None or truth(self.evaluate(node.condition)):
                if not self.loop_body(node.body):
                    break
                if node.update is not None:
                    self.evaluate(node.update)
        elif kind == "for_in":
            keys = sorted(self.variable(node.array.binding), key=subscript_order)
            for key in keys:
                location = ("variable", node.variable.binding)
                self.store(location, input_value(key), node.variable.position)
                if not self.loop_body(node.body):
                    break
        elif kind == "delete":
            array = self.variable(node.array.binding)
            if node.indexes is None:
                array.clear()
            else:
                key = self.subscript(node.indexes)
                array.pop(key, None)
        elif kind == "next":
            if self.phase in ("BEGIN", "END"):
                raise RuntimeIssue(node.position, "next used in BEGIN or END")
            raise Transfer("next")
        elif kind == "exit":
            if node.value is not None:
                self.exit_status = to_number(self.evaluate(node.value))
            raise Transfer("exit")
        elif kind == "return":
            value = self.evaluate(node.value) if node.value is not None else UNINITIALIZED
            raise Transfer("return", value)
        else:
            raise Transfer(kind)

    def next_record(self):
        while True:
            if self.input_position < len(self.input_lines):
                line = self.input_lines[self.input_position]
                self.input_position += 1
                self.current_operand.records += 1
                self.globals["NR"] = number(to_number(self.global_value("NR")) + 1)
                self.globals["FNR"] = number(to_number(self.global_value("FNR")) + 1)
                return line
            if self.operand_position == len(self.operands):
                return None
            operand = self.operands[self.operand_position]
            self.operand_position += 1
            if operand.kind == "assignment":
                self.assign_global_input(operand.name, operand.value)
            else:
                self.current_operand = operand
                self.input_lines = read_records(operand.name)
                self.input_position = 0
                self.globals["FILENAME"] = string(operand.name)
                self.globals["FNR"] = number(0)

    def run_actions(self, phase):
        self.phase = phase
        for rule in self.analysis.rules:
            if rule.flavor == phase:
                rule.count += 1
                self.statement(rule.action)

    def matches(self, rule):
        if rule.flavor == "all":
            return True
        if rule.flavor == "pattern":
            return truth(self.evaluate(rule.patterns[0]))
        if not rule.inside and truth(self.evaluate(rule.patterns[0])):
            rule.inside = True
        if not rule.inside:
            return False
        if truth(self.evaluate(rule.patterns[1])):
            rule.inside = False
        return True

    def run_records(self):
        if not any(rule.flavor != "BEGIN" for rule in self.analysis.rules):
            return
        self.phase = "records"
        rules = [rule for rule in self.analysis.rules if rule.flavor not in ("BEGIN", "END")]
        while True:
            line = self.next_record()
            if line is None:
                return
            self.record.set(line)
            try:
                for rule in rules:
                    if self.matches(rule):
                        rule.count += 1
                        if rule.action is None:
                            text = to_string(self.record.zero) + to_string(self.global_value("ORS"))
                            self.streams.write(text)
                        else:
                            self.statement(rule.action)
            except Transfer as transfer:
                if transfer.kind != "next":
                    raise

    def execute(self):
        try:
            for name, text in self.options:
                self.assign_global_input(name, text)
            try:
                self.run_actions("BEGIN")
                self.run_records()
            except Transfer as transfer:
                if transfer.kind != "exit":
                    raise
            try:
                self.run_actions("END")
            except Transfer as transfer:
                if transfer.kind != "exit":
                    raise
        except RuntimeIssue as error:
            self.error = error

    def statistics(self):
        if self.error is None:
            status = f"status: exit {self.exit_status}"
        else:
            line, column = self.error.position
            status = f"status: runtime error at {line}:{column}: {self.error.message}"
        lines = [status, "[inputs]"]
        for operand in self.operands:
            if operand.kind == "file":
                lines.append(f"{operand.name} records={operand.records}")
        lines.append("[getline]")
        for name, source in self.streams.inputs.items():
            suffix = f"reads={source.reads}" if source.ever_opened else "missing"
            lines.append(f"{name} {suffix}")
        lines.append("[rules]")
        for rule in self.analysis.rules:
            line, column = rule.position
            lines.append(f"{line}:{column} {rule.flavor} count={rule.count}")
        lines.append("[functions]")
        for function in self.analysis.functions:
            lines.append(f"{function.name} calls={function.call_count} depth={function.max_depth}")
        lines.append("[outputs]")
        stdout = self.streams.stdout
        lines.append(f"stdout.txt writes={stdout.writes} bytes={len(stdout.content())}")
        for name, output in self.streams.outputs.items():
            lines.append(f"{name} writes={output.writes} bytes={len(output.content())}")
        lines.append("[lines]")
        for line in sorted(self.lines):
            lines.append(f"{line} count={self.lines[line]}")
        lines.append("[globals]")
        for name in sorted(self.global_names):
            value = self.global_value(name)
            text = f"array ({len(value)})" if (None, name) in self.analysis.array_names else describe(value)
            lines.append(f"{name} = {text}")
        return lines


def main():
    sys.setrecursionlimit(100000)
    options, operands = parse_arguments(Path("input/args.txt").read_text(encoding="ascii"))
    source = Path("input/program.awk").read_text(encoding="ascii")
    try:
        items = Parser(tokenize(source)).parse()
        analysis = Analysis(items).prepare()
    except SyntaxIssue as error:
        line, column = error.position
        statistics = [f"status: syntax error at {line}:{column}"]
        streams = Streams()
    except StaticIssue as error:
        line, column = error.position
        statistics = [f"status: error at {line}:{column}: {error.message}"]
        streams = Streams()
    else:
        engine = Engine(analysis, options, operands)
        engine.execute()
        statistics = engine.statistics()
        streams = engine.streams
    streams.save()
    Path("output/stats.txt").write_text("\n".join(statistics) + "\n", encoding="ascii", newline="\n")


if __name__ == "__main__":
    main()

from lexer import SyntaxIssue


ASSIGNMENTS = frozenset(("=", "+=", "-=", "*=", "/=", "%=", "^="))
COMPARISONS = frozenset(("<", "<=", "==", "!=", ">=", ">"))
LVALUE_KINDS = frozenset(("name", "array", "field"))
STATEMENTS = frozenset(("if", "while", "do", "for", "for_in", "print", "printf", "delete",
                        "next", "break", "continue", "exit", "return", "expression_statement"))


class Node:
    def __init__(self, kind, position, children=(), **fields):
        self.kind, self.position = kind, position
        self.children = [child for child in children if child is not None]
        self.__dict__.update(fields)


class Parser:
    def __init__(self, tokens):
        self.tokens, self.position = tokens, 0
        self.function = False
        self.phase = None
        self.loop_depth = 0

    def peek(self):
        return self.tokens[self.position]

    def take(self):
        token = self.peek()
        self.position += 1
        return token

    def fail(self, position=None):
        raise SyntaxIssue(self.peek().position if position is None else position)

    def accept(self, spelling):
        return self.take() if self.peek().spelling == spelling else None

    def expect(self, spelling):
        if self.peek().spelling != spelling:
            self.fail()
        return self.take()

    def name(self):
        if self.peek().kind != "name":
            self.fail()
        token = self.take()
        return Node("name", token.position, name=token.spelling)

    def newlines(self):
        while self.accept("\n"):
            pass

    def parse(self):
        items = []
        while self.peek().kind != "end":
            if self.peek().spelling in ("\n", ";"):
                self.take()
                continue
            start = self.peek()
            if self.accept("function"):
                if self.peek().kind not in ("name", "function_name"):
                    self.fail()
                name = self.take()
                self.expect("(")
                parameters = []
                if self.peek().spelling != ")":
                    while True:
                        parameter = self.name()
                        parameter.kind = "parameter"
                        parameters.append(parameter)
                        if not self.accept(","):
                            break
                        self.newlines()
                self.expect(")")
                self.newlines()
                self.function = True
                body = self.block()
                self.function = False
                items.append(Node("function", start.position, [*parameters, body], name=name.spelling,
                                  name_position=name.position, parameters=parameters, body=body))
                continue
            patterns = []
            if start.spelling in ("BEGIN", "END"):
                flavor = self.take().spelling
            elif start.spelling == "{":
                flavor = "all"
            else:
                patterns.append(self.expression())
                if self.accept(","):
                    self.newlines()
                    patterns.append(self.expression())
                flavor = "range" if len(patterns) == 2 else "pattern"
            self.phase = flavor
            if flavor in ("BEGIN", "END", "all") or self.peek().spelling == "{":
                action = self.block()
            else:
                if self.peek().spelling not in ("\n", ";") and self.peek().kind != "end":
                    self.fail()
                action = None
            self.phase = None
            items.append(Node("rule", start.position, [*patterns, action], flavor=flavor,
                              patterns=patterns, action=action))
        return items

    def block(self):
        opening = self.expect("{")
        statements = []
        while self.peek().spelling != "}":
            if self.peek().spelling in ("\n", ";"):
                self.take()
            else:
                statements.append(self.statement())
        self.expect("}")
        return Node("block", opening.position, statements, statements=statements)

    def condition(self):
        self.expect("(")
        value = self.expression()
        self.expect(")")
        return value

    def loop_body(self):
        self.newlines()
        self.loop_depth += 1
        body = self.statement()
        self.loop_depth -= 1
        return body

    def terminator(self):
        if self.peek().spelling in (";", "\n"):
            self.take()
        elif self.peek().spelling != "}":
            self.fail()

    def statement(self):
        token = self.peek()
        spelling = token.spelling
        if spelling == "{":
            return self.block()
        if self.accept(";"):
            return Node("empty", token.position)
        if self.accept("if"):
            condition = self.condition()
            self.newlines()
            first = self.statement()
            self.newlines()
            second = None
            if self.accept("else"):
                self.newlines()
                second = self.statement()
            return Node("if", token.position, [condition, first, second], condition=condition, first=first, second=second)
        if self.accept("while"):
            condition = self.condition()
            body = self.loop_body()
            return Node("while", token.position, [condition, body], condition=condition, body=body)
        if self.accept("do"):
            body = self.loop_body()
            self.newlines()
            self.expect("while")
            condition = self.condition()
            self.terminator()
            return Node("do", token.position, [body, condition], body=body, condition=condition)
        if self.accept("for"):
            self.expect("(")
            ahead = self.tokens[self.position:self.position + 4]
            if len(ahead) == 4 and ahead[0].kind == "name" and ahead[1].spelling == "in" and ahead[2].kind == "name" and ahead[3].spelling == ")":
                variable = self.name()
                self.expect("in")
                array = self.name()
                self.expect(")")
                body = self.loop_body()
                return Node("for_in", token.position, [variable, array, body], variable=variable, array=array, body=body)
            initial = self.expression() if self.peek().spelling != ";" else None
            self.expect(";")
            self.newlines()
            condition = self.expression() if self.peek().spelling != ";" else None
            self.expect(";")
            self.newlines()
            update = self.expression() if self.peek().spelling != ")" else None
            self.expect(")")
            body = self.loop_body()
            return Node("for", token.position, [initial, condition, update, body], initial=initial,
                        condition=condition, update=update, body=body)
        if spelling in ("print", "printf"):
            self.take()
            result = self.output_statement(token)
        elif spelling == "delete":
            self.take()
            array = self.name()
            indexes = None
            if self.accept("["):
                indexes = self.expression_list()
                self.expect("]")
            result = Node("delete", token.position, [array, *(indexes or [])], array=array, indexes=indexes)
        elif spelling in ("next", "break", "continue", "exit", "return"):
            self.take()
            if spelling == "next" and not self.function and self.phase in ("BEGIN", "END"):
                self.fail(token.position)
            if spelling == "return" and not self.function:
                self.fail(token.position)
            if spelling in ("break", "continue") and self.loop_depth == 0:
                self.fail(token.position)
            value = None
            if spelling in ("exit", "return") and self.peek().spelling not in (";", "\n", "}"):
                value = self.expression()
            result = Node(spelling, token.position, [value], value=value)
        else:
            expression = self.expression()
            result = Node("expression_statement", token.position, [expression], expression=expression)
        self.terminator()
        return result

    def parenthesized_output(self):
        if self.peek().spelling != "(":
            return False
        depth = 0
        for index in range(self.position, len(self.tokens)):
            spelling = self.tokens[index].spelling
            if spelling == "(":
                depth += 1
            elif spelling == ")":
                depth -= 1
                if depth == 0:
                    next_token = self.tokens[index + 1]
                    return next_token.spelling in (";", "\n", "}", ">", ">>") or next_token.kind == "end"
        return False

    def output_statement(self, token):
        arguments = []
        if self.parenthesized_output():
            self.expect("(")
            arguments = self.expression_list()
            self.expect(")")
        elif self.peek().spelling not in (";", "\n", "}", ">", ">>"):
            arguments = self.expression_list(greater=False)
        if token.spelling == "printf" and not arguments:
            self.fail()
        redirect = self.take() if self.peek().spelling in (">", ">>") else None
        filename = self.concatenation() if redirect is not None else None
        return Node(token.spelling, token.position, [*arguments, filename], arguments=arguments,
                    redirect=redirect.spelling if redirect else None,
                    redirect_position=redirect.position if redirect else None, filename=filename)

    def expression_list(self, greater=True):
        result = [self.expression(greater)]
        while self.accept(","):
            self.newlines()
            result.append(self.expression(greater))
        return result

    def expression(self, greater=True):
        left = self.conditional(greater)
        if left.kind in LVALUE_KINDS and self.peek().spelling in ASSIGNMENTS:
            operator = self.take()
            right = self.expression(greater)
            return Node("assignment", operator.position, [left, right], operator=operator.spelling,
                        location=left, value=right)
        return left

    def conditional(self, greater):
        condition = self.logical(0, greater)
        operator = self.accept("?")
        if operator is None:
            return condition
        first = self.conditional(greater)
        self.expect(":")
        second = self.conditional(greater)
        return Node("conditional", operator.position, [condition, first, second],
                    condition=condition, first=first, second=second)

    def binary(self, operator, left, right):
        return Node("binary", operator.position, [left, right], operator=operator.spelling, left=left, right=right)

    def logical(self, level, greater):
        if level == 2:
            return self.membership(greater)
        operator_name = "||" if level == 0 else "&&"
        left = self.logical(level + 1, greater)
        while self.peek().spelling == operator_name:
            operator = self.take()
            self.newlines()
            left = self.binary(operator, left, self.logical(level + 1, greater))
        return left

    def membership(self, greater):
        left = self.comparison(greater)
        while self.peek().spelling == "in":
            operator = self.take()
            array = self.name()
            left = Node("membership", operator.position, [left, array], indexes=[left], array=array)
        return left

    def comparison(self, greater):
        left = self.concatenation()
        while self.peek().spelling in COMPARISONS and (greater or self.peek().spelling != ">"):
            operator = self.take()
            left = self.binary(operator, left, self.concatenation())
        return left

    def concatenation(self):
        left = self.additive()
        while self.peek().kind in ("number", "string", "name", "function_name", "builtin") or self.peek().spelling in ("$", "(", "++", "--"):
            position = self.peek().position
            right = self.additive()
            left = Node("binary", position, [left, right], operator="concat", left=left, right=right)
        return left

    def additive(self):
        left = self.multiplicative()
        while self.peek().spelling in ("+", "-"):
            operator = self.take()
            left = self.binary(operator, left, self.multiplicative())
        return left

    def multiplicative(self):
        left = self.unary()
        while self.peek().spelling in ("*", "/", "%"):
            operator = self.take()
            left = self.binary(operator, left, self.unary())
        return left

    def unary(self):
        if self.peek().spelling in ("!", "-", "+"):
            operator = self.take()
            operand = self.unary()
            return Node("unary", operator.position, [operand], operator=operator.spelling, operand=operand)
        left = self.postfix()
        if self.peek().spelling == "^":
            operator = self.take()
            left = self.binary(operator, left, self.unary())
        return left

    def prefix(self):
        operator = self.take()
        location = self.lvalue()
        return Node("increment", operator.position, [location], location=location,
                    delta=1 if operator.spelling == "++" else -1, prefix=True)

    def postfix(self):
        if self.peek().spelling in ("++", "--"):
            return self.prefix()
        left = self.atom()
        if left.kind in LVALUE_KINDS and self.peek().spelling in ("++", "--"):
            operator = self.take()
            return Node("increment", operator.position, [left], location=left,
                        delta=1 if operator.spelling == "++" else -1, prefix=False)
        return left

    def lvalue(self):
        if self.peek().kind == "name":
            node = self.name()
            if self.accept("["):
                indexes = self.expression_list()
                self.expect("]")
                return Node("array", node.position, indexes, name=node.name, indexes=indexes)
            return node
        dollar = self.accept("$")
        if dollar is not None:
            index = self.prefix() if self.peek().spelling in ("++", "--") else self.atom()
            return Node("field", dollar.position, [index], index=index)
        self.fail()

    def atom(self):
        token = self.peek()
        if token.kind in ("number", "string"):
            self.take()
            return Node(token.kind, token.position, value=token.value)
        if token.kind == "name" or token.spelling == "$":
            return self.lvalue()
        if self.accept("("):
            expressions = self.expression_list()
            self.expect(")")
            if len(expressions) == 1:
                return Node("paren", token.position, expressions, expression=expressions[0])
            self.expect("in")
            array = self.name()
            return Node("membership", token.position, [*expressions, array], indexes=expressions, array=array)
        if token.kind in ("function_name", "builtin"):
            self.take()
            arguments = []
            if self.accept("("):
                if self.peek().spelling != ")":
                    arguments = self.expression_list()
                self.expect(")")
            elif token.kind == "function_name" or token.spelling != "length":
                self.fail()
            kind = "call" if token.kind == "function_name" else "builtin"
            if kind == "builtin":
                self.check_builtin(token, arguments)
            return Node(kind, token.position, arguments, name=token.spelling, arguments=arguments)
        if self.accept("getline"):
            target = self.lvalue() if self.peek().kind == "name" or self.peek().spelling == "$" else None
            filename = self.atom() if self.accept("<") else None
            return Node("getline", token.position, [target, filename], target=target, filename=filename)
        self.fail()

    def check_builtin(self, token, arguments):
        count, name = len(arguments), token.spelling
        if name == "length":
            valid = count in (0, 1)
        elif name in ("substr", "split"):
            valid = count in (2, 3)
        elif name == "index":
            valid = count == 2
        elif name == "sprintf":
            valid = count >= 1
        else:
            valid = count == 1
        if not valid or name == "split" and arguments[1].kind != "name":
            self.fail(token.position)

from pathlib import Path

from awk_builtins import RuntimeIssue


def letter(character):
    return "a" <= character <= "z" or "A" <= character <= "Z"


def valid_name(name):
    return bool(name) and (letter(name[0]) or name[0] == "_") and all(
        letter(character) or "0" <= character <= "9" or character == "_" for character in name)


def valid_filename(name):
    return bool(name) and not name.startswith(".") and all(
        letter(character) or "0" <= character <= "9" or character in "._-" for character in name)


class Operand:
    def __init__(self, kind, name, value=None):
        self.kind, self.name, self.value = kind, name, value
        self.records = 0


def parse_arguments(text):
    options, operands = [], []
    for line in text.splitlines():
        if line.startswith("-F "):
            options.append(("FS", line[3:]))
        elif line.startswith("-v "):
            name, value = line[3:].split("=", 1)
            options.append((name, value))
        elif "=" in line and valid_name(line.split("=", 1)[0]):
            name, value = line.split("=", 1)
            operands.append(Operand("assignment", name, value))
        else:
            operands.append(Operand("file", line))
    return options, operands


def read_records(name):
    return Path("input", name).read_text(encoding="ascii").splitlines()


class Output:
    def __init__(self):
        self.parts = []
        self.open = False
        self.writes = 0

    def append(self, text):
        self.parts.append(text)
        self.writes += 1

    def content(self):
        return "".join(self.parts)


class GetlineInput:
    def __init__(self):
        self.open = False
        self.ever_opened = False
        self.lines = []
        self.position = 0
        self.reads = 0


class Streams:
    def __init__(self):
        self.stdout = Output()
        self.outputs = {}
        self.inputs = {}

    def write(self, text, name=None, mode=None, position=None):
        if name is None:
            self.stdout.append(text)
            return
        if not valid_filename(name) or name in ("stdout.txt", "stats.txt"):
            raise RuntimeIssue(position, "invalid output file name")
        if name not in self.outputs:
            self.outputs[name] = Output()
        output = self.outputs[name]
        if not output.open:
            output.open = True
            if mode == ">":
                output.parts = []
        output.append(text)

    def getline(self, name):
        if name not in self.inputs:
            self.inputs[name] = GetlineInput()
        source = self.inputs[name]
        if not source.open:
            if not valid_filename(name) or not Path("input", name).is_file():
                return -1, None
            source.lines = read_records(name)
            source.position = 0
            source.open = source.ever_opened = True
        if source.position == len(source.lines):
            return 0, None
        line = source.lines[source.position]
        source.position += 1
        source.reads += 1
        return 1, line

    def close(self, name):
        closed = False
        for table in (self.outputs, self.inputs):
            if name in table and table[name].open:
                table[name].open = False
                closed = True
        return 0 if closed else -1

    def save(self):
        output = Path("output")
        output.mkdir(exist_ok=True)
        (output / "stdout.txt").write_text(self.stdout.content(), encoding="ascii", newline="\n")
        for name, stream in self.outputs.items():
            (output / name).write_text(stream.content(), encoding="ascii", newline="\n")

from collections import namedtuple


Value = namedtuple("Value", "kind text numeric")
UNINITIALIZED = Value("uninitialized", None, 0)
WHITESPACE = " \t\n"


def number(value):
    return Value("number", None, value)


def string(value):
    return Value("string", value, None)


def numeric_prefix(text):
    text = text.lstrip(WHITESPACE)
    index, sign = 0, 1
    if text.startswith(("+", "-")):
        sign = -1 if text[0] == "-" else 1
        index = 1
    start = index
    while index < len(text) and "0" <= text[index] <= "9":
        index += 1
    return sign * int(text[start:index]) if index > start else 0


def input_value(text):
    trimmed = text.strip(WHITESPACE)
    digits = trimmed[1:] if trimmed.startswith(("+", "-")) else trimmed
    if digits and all("0" <= character <= "9" for character in digits):
        return Value("strnum", text, numeric_prefix(trimmed))
    return string(text)


def to_number(value):
    return numeric_prefix(value.text) if value.kind == "string" else value.numeric


def to_string(value):
    if value.kind == "number":
        return str(value.numeric)
    if value.kind == "uninitialized":
        return ""
    return value.text


def truth(value):
    return bool(value.text) if value.kind == "string" else value.numeric != 0


def compare(first, second):
    if first.kind != "string" and second.kind != "string":
        a, b = to_number(first), to_number(second)
    else:
        a, b = to_string(first), to_string(second)
    return (a > b) - (a < b)


def subscript_order(text):
    digits = text[1:] if text.startswith("-") else text
    if text == "0" or digits and "1" <= digits[0] <= "9" and all("0" <= character <= "9" for character in digits):
        return 0, int(text)
    return 1, text


def split_pieces(text, separator):
    if not text:
        return []
    if separator == "":
        return list(text)
    if separator != " ":
        return text.split(separator)
    pieces, start = [], None
    for index, character in enumerate(text):
        if character in WHITESPACE:
            if start is not None:
                pieces.append(text[start:index])
                start = None
        elif start is None:
            start = index
    if start is not None:
        pieces.append(text[start:])
    return pieces


class Record:
    def __init__(self, special):
        self.special = special
        self.zero = string("")
        self.fields = []

    def set(self, text):
        self.zero = input_value(text)
        separator = to_string(self.special("FS"))
        self.fields = [input_value(piece) for piece in split_pieces(text, separator)]

    def read(self, index):
        if index == 0:
            return self.zero
        return self.fields[index - 1] if index <= len(self.fields) else UNINITIALIZED

    def rebuild(self):
        separator = to_string(self.special("OFS"))
        self.zero = input_value(separator.join(to_string(value) for value in self.fields))

    def write(self, index, value):
        if index == 0:
            self.set(to_string(value))
            return
        if index > len(self.fields):
            self.fields.extend(string("") for _ in range(index - len(self.fields)))
        self.fields[index - 1] = value
        self.rebuild()

    def resize(self, size):
        if size < len(self.fields):
            del self.fields[size:]
        else:
            self.fields.extend(string("") for _ in range(size - len(self.fields)))
        self.rebuild()


def quoted(text):
    parts = ['"']
    escapes = {'"': '\\"', "\\": "\\\\", "\n": "\\n", "\t": "\\t"}
    for character in text:
        if character in escapes:
            parts.append(escapes[character])
        elif 32 <= ord(character) <= 126:
            parts.append(character)
        else:
            parts.append("\\" + format(ord(character), "03o"))
    parts.append('"')
    return "".join(parts)


def describe(value):
    if value.kind == "number":
        return str(value.numeric)
    if value.kind == "uninitialized":
        return "(uninitialized)"
    return quoted(value.text) + (" (strnum)" if value.kind == "strnum" else "")
